function renderPeriodChips() {
  let el = refs.periodChips;
  if (!el) {
    el = createEl('div', {
      style: {
        display: 'flex', gap: 'var(--s-1)', flexWrap: 'wrap',
        marginTop: 'var(--s-3)', marginBottom: 'var(--s-4)',
 }
 });
    refs.periodChips = el;
    rootEl.appendChild(el);
 }
  el.innerHTML = '';
  PERIODS.forEach(d => {
    const chip = createEl('button', {
      class:  btn btn--sm ${state.days === d ? 'btn--primary' : 'btn--secondary'} ,
      style: {
        padding: 'var(--s-1) var(--s-3)', fontSize: 'var(--text-xs)', fontWeight: 600,
        borderRadius: '16px',
 }
 });
    chip.textContent = d + 'H';
    on(chip, 'click', () => {
      if (state.days === d) return;
      state.days = d;
      renderPeriodChips();
      loadMarket();
 });
    el.appendChild(chip);
 });
}

function fullDate(dateStr) {
  const d = new Date(dateStr);
  if (isNaN(d)) return dateStr;
  const months = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
  return  ${d.getDate()} ${months[d.getMonth()]} ${d.getFullYear()} ;
}

function clearCompare() {
  state.compareTickers = [];
  state.compareData = {};
  state.compareMode = false;
  if (refs.compareBar) {
    refs.compareBar.remove();
    refs.compareBar = null;
 }
}

